<template>
  <div class="kvm-page clusters-page">
    <header class="clusters-header">
      <div><span class="eyebrow">SUSE LINUX ENTERPRISE HIGH AVAILABILITY</span><h1>{{ t('clusters.title') }}</h1><p>{{ t('clusters.subtitle') }}</p></div>
      <button class="btn role-secondary" :disabled="loading || refreshingStale" @click="load">{{ loading || refreshingStale ? t('clusters.refreshing') : t('clusters.refresh') }}</button>
    </header>

    <div v-if="error" class="banner error" role="alert">{{ error }}</div>
    <div v-if="loading && !loaded" class="loading">{{ t('clusters.loading') }}</div>
    <template v-else>
      <div class="cluster-stats">
        <article><span>{{ t('clusters.registeredHosts') }}</span><strong>{{ hosts.length }}</strong></article>
        <article><span>{{ t('clusters.haEnabledHosts') }}</span><strong>{{ haEnabledCount }}</strong><small>{{ t('clusters.haEnabledHostsHelp') }}</small></article>
        <article><span>{{ t('clusters.clusterHosts') }}</span><strong>{{ clusterHostCount }}</strong><small>{{ t('clusters.clusterHostsHelp') }}</small></article>
      </div>

      <nav class="cluster-nav" role="tablist" :aria-label="t('clusters.navigation')">
        <button v-for="section in sections" :key="section" class="cluster-nav-item" role="tab" :aria-selected="activeSection === section" :aria-controls="`cluster-panel-${section}`" @click="selectSection(section)">
          <span class="nav-icon" aria-hidden="true">{{ sectionIcon(section) }}</span>{{ t(`clusters.section_${section}`) }}
          <span v-if="section === 'nodes'" class="nav-count">{{ hosts.length }}</span>
        </button>
      </nav>

      <section v-if="activeSection === 'clusters'" id="cluster-panel-clusters" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.inventoryTitle') }}</h2><p>{{ t('clusters.inventoryDescription') }}</p></div><button class="btn role-primary" @click="activeSection = 'plan'">{{ t('clusters.startPlanning') }}</button></div>
        <div v-if="clusterHostCount === 0" class="empty-state"><div class="preview-icon" aria-hidden="true">◇</div><h3>{{ t('clusters.noClusters') }}</h3><p>{{ t('clusters.noClustersHelp') }}</p><button class="btn role-primary" @click="activeSection = 'plan'">{{ t('clusters.planFirstCluster') }}</button></div>
        <template v-else>
          <div class="cluster-source-list"><article v-for="host in clusterHosts" :key="host.id" class="cluster-source-card"><div><strong>{{ host.ha?.cluster_name || host.hostname || host.name }}</strong><small>{{ t('clusters.reportedBy', { host: host.hostname || host.name }) }}</small><span class="state" :class="host.ha?.ha_active ? 'ready' : 'warning-state'"><i></i>{{ host.ha?.cluster_detected ? t('clusters.clusterDetected') : t('clusters.clusterNotInitialized') }}</span></div><button class="btn role-primary btn-sm" :disabled="clusterStatusLoading" @click="openCluster(host)">{{ t('clusters.openCluster') }}</button></article></div>
          <div v-if="clusterStatusLoading" class="loading compact">{{ t('clusters.clusterLoading') }}</div>
          <div v-if="clusterStatusError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.clusterStatusError') }}</strong><p>{{ clusterStatusError }}</p></div>
          <template v-if="clusterStatus">
            <div class="cluster-detail-heading"><div><span class="eyebrow">{{ t('clusters.liveStatus') }}</span><h3>{{ clusterStatus.cluster_name || t('clusters.unnamedCluster') }}</h3><small>{{ t('clusters.statusSource', { host: clusterStatus.source_host_name }) }} · {{ dateLabel(clusterStatus.checked_at) }}</small></div><div class="cluster-heading-actions"><a v-if="clusterDiagnostics?.hawk_url" class="btn role-secondary btn-sm" :href="clusterDiagnostics.hawk_url" target="_blank" rel="noopener noreferrer">{{ t('clusters.openHawk') }}</a><button class="btn role-secondary btn-sm" :disabled="clusterStatusLoading" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div></div>
            <div class="cluster-detail-stats"><article><small>{{ t('clusters.nodes') }}</small><strong>{{ clusterStatus.online_count || 0 }} / {{ clusterStatus.node_count || 0 }}</strong><span>{{ t('clusters.onlineNodes') }}</span></article><article><small>{{ t('clusters.resources') }}</small><strong>{{ clusterStatus.resource_count || 0 }}</strong><span>{{ t('clusters.managedResources') }}</span></article><article><small>{{ t('clusters.quorum') }}</small><strong :class="clusterStatus.quorum?.quorate ? 'healthy-text' : 'warning-text'">{{ clusterStatus.quorum?.quorate ? t('clusters.quorate') : clusterStatus.quorum?.available ? t('clusters.notQuorate') : t('clusters.quorumUnknown') }}</strong><span>{{ quorumSummary }}</span></article><article><small>{{ t('clusters.fencing') }}</small><strong :class="clusterStatus.fencing?.configured ? 'healthy-text' : 'warning-text'">{{ clusterStatus.fencing?.configured ? t('clusters.fencingConfigured') : clusterStatus.fencing?.available ? t('clusters.fencingNotConfigured') : t('clusters.fencingUnknown') }}</strong><span>{{ fencingSummary }}</span></article></div>
            <div class="cluster-shortcuts"><button class="btn role-link" @click="activeSection = 'nodes'">{{ t('clusters.manageNodes') }}</button><button class="btn role-link" @click="activeSection = 'resources'">{{ t('clusters.manageResources') }}</button><button class="btn role-link" @click="activeSection = 'fencing'">{{ t('clusters.reviewQuorumFencing') }}</button></div>
          </template>
        </template>
        <p class="safety-note">{{ t('clusters.inventorySeparation') }}</p>
      </section>

      <section v-else-if="activeSection === 'nodes' || activeSection === 'resources'" :id="`cluster-panel-${activeSection}`" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t(`clusters.section_${activeSection}`) }}</h2><p>{{ t(`clusters.area_${activeSection}_description`) }}</p></div><button class="btn role-secondary" :disabled="clusterStatusLoading || !activeClusterHostId" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div>
        <div v-if="!clusterStatus && !clusterStatusLoading" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ clusterStatusError || t('clusters.noLiveClusterHelp') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <template v-else-if="clusterStatus">
          <div v-if="activeSection === 'nodes'" class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.node') }}</th><th>{{ t('clusters.nodeStatus') }}</th><th>{{ t('clusters.standby') }}</th><th>{{ t('clusters.maintenance') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody><tr v-for="node in clusterStatus.nodes" :key="node.id || node.name"><td><strong>{{ node.name }}</strong><small>{{ t('clusters.nodeId') }}: {{ node.id || '—' }}</small></td><td><span class="state" :class="node.online && !node.unclean ? 'ready' : 'unreachable'"><i></i>{{ node.online ? (node.unclean ? t('clusters.unclean') : t('clusters.online')) : t('clusters.offline') }}</span><small v-if="node.pending">{{ node.pending }}</small></td><td>{{ node.standby ? t('clusters.enabledState') : t('clusters.disabledState') }}</td><td>{{ node.maintenance ? t('clusters.enabledState') : t('clusters.disabledState') }}</td><td class="action-cell"><button v-if="!node.standby" class="btn role-secondary btn-sm" @click="requestClusterAction('node_standby', node.name)">{{ t('clusters.standbyNode') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('node_online', node.name)">{{ t('clusters.bringOnline') }}</button><button v-if="!node.maintenance" class="btn role-secondary btn-sm" @click="requestClusterAction('node_maintenance', node.name)">{{ t('clusters.enterMaintenance') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('node_ready', node.name)">{{ t('clusters.leaveMaintenance') }}</button></td></tr></tbody></table></div>
          <div v-else class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.resource') }}</th><th>{{ t('clusters.resourceType') }}</th><th>{{ t('clusters.resourceStatus') }}</th><th>{{ t('clusters.location') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody><tr v-for="resource in clusterStatus.resources" :key="resource.id"><td><strong>{{ resource.id }}</strong></td><td>{{ resource.agent || '—' }}</td><td><span class="state" :class="resource.failed ? 'unreachable' : resource.active ? 'ready' : 'warning-state'"><i></i>{{ resource.failed ? t('clusters.failed') : resource.active ? (resource.role || t('clusters.running')) : t('clusters.stopped') }}</span><small v-if="!resource.managed">{{ t('clusters.unmanaged') }}</small></td><td>{{ resource.nodes?.join(', ') || '—' }}</td><td class="action-cell"><button v-if="resource.active" class="btn role-secondary btn-sm" @click="requestClusterAction('resource_stop', resource.id)">{{ t('clusters.stopResource') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('resource_start', resource.id)">{{ t('clusters.startResource') }}</button><button v-if="resource.failed" class="btn role-secondary btn-sm" @click="requestClusterAction('resource_cleanup', resource.id)">{{ t('clusters.cleanupResource') }}</button></td></tr><tr v-if="!clusterStatus.resources?.length"><td colspan="5" class="empty-row">{{ t('clusters.noResources') }}</td></tr></tbody></table></div>
        </template>
        <div v-if="!canManageCluster && clusterStatus" class="inline-callout info"><strong>{{ t('clusters.readOnly') }}</strong><p>{{ t('clusters.operatorRoleRequired') }}</p></div>
        <div v-if="pendingClusterAction" class="inline-callout warning action-review"><strong>{{ t('clusters.confirmActionTitle') }}</strong><p>{{ actionReviewText }}</p><small>{{ t('clusters.actionRiskNote') }}</small><div><button class="btn role-primary btn-sm" :disabled="clusterActionBusy" @click="runClusterAction">{{ clusterActionBusy ? t('clusters.actionRunning') : t('clusters.confirmAction') }}</button><button class="btn role-secondary btn-sm" :disabled="clusterActionBusy" @click="pendingClusterAction = null">{{ t('clusters.cancelAction') }}</button></div></div>
        <div v-if="clusterActionError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.actionFailed') }}</strong><p>{{ clusterActionError }}</p></div><div v-if="clusterActionMessage" class="inline-callout success" role="status"><strong>{{ t('clusters.actionSucceeded') }}</strong><p>{{ clusterActionMessage }}</p></div>
        <p class="safety-note">{{ t('clusters.nodeActionSafety') }}</p>
      </section>

      <section v-else-if="activeSection === 'fencing'" id="cluster-panel-fencing" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.section_fencing') }}</h2><p>{{ t('clusters.fencingDetailDescription') }}</p></div><button class="btn role-secondary" :disabled="clusterStatusLoading || !activeClusterHostId" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div>
        <div v-if="clusterStatus" class="fencing-grid"><article><span class="state" :class="clusterStatus.quorum?.quorate ? 'ready' : 'warning-state'"><i></i>{{ clusterStatus.quorum?.quorate ? t('clusters.quorate') : clusterStatus.quorum?.available ? t('clusters.notQuorate') : t('clusters.quorumUnknown') }}</span><pre v-if="clusterStatus.quorum?.summary">{{ clusterStatus.quorum.summary }}</pre><p v-else>{{ t('clusters.quorumHelp') }}</p></article><article><span class="state" :class="clusterStatus.fencing?.configured ? 'ready' : 'warning-state'"><i></i>{{ clusterStatus.fencing?.configured ? t('clusters.fencingConfigured') : clusterStatus.fencing?.available ? t('clusters.fencingNotConfigured') : t('clusters.fencingUnknown') }}</span><pre v-if="clusterStatus.fencing?.summary">{{ clusterStatus.fencing.summary }}</pre><p v-else>{{ t('clusters.fencingHelp') }}</p></article></div><div v-else class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ clusterStatusError || t('clusters.noLiveClusterHelp') }}</p></div>
        <article v-if="clusterDiagnostics" class="diagnostic-card"><h3>{{ t('clusters.corosyncLinks') }}</h3><pre v-if="clusterDiagnostics.corosync?.available">{{ clusterDiagnostics.corosync.summary }}</pre><p v-else>{{ clusterDiagnostics.corosync?.error || t('clusters.diagnosticsUnavailable') }}</p></article>
        <div class="inline-callout warning"><strong>{{ t('clusters.twoNodeTitle') }}</strong><p>{{ t('clusters.fencingBestPractice') }}</p></div>
      </section>

      <section v-else-if="activeSection === 'constraints'" id="cluster-panel-constraints" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.section_constraints') }}</h2><p>{{ t('clusters.area_constraints_description') }}</p></div><button class="btn role-secondary" :disabled="diagnosticsLoading || !activeClusterHostId" @click="fetchClusterDiagnostics">{{ diagnosticsLoading ? t('clusters.diagnosticsLoading') : t('clusters.refresh') }}</button></div>
        <div v-if="!activeClusterHostId" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ t('clusters.selectClusterForDetails') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <div v-else-if="diagnosticsLoading" class="loading compact">{{ t('clusters.diagnosticsLoading') }}</div>
        <template v-else-if="clusterDiagnostics || clusterDiagnosticsError">
          <div v-if="clusterDiagnosticsError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.diagnosticsError') }}</strong><p>{{ clusterDiagnosticsError }}</p></div>
          <div class="constraint-groups"><article v-for="kind in ['location','ordering','colocation']" :key="kind" class="diagnostic-card"><h3>{{ t(`clusters.constraint_${kind}`) }}</h3><ul v-if="clusterDiagnostics.constraints?.[kind]?.items?.length"><li v-for="item in clusterDiagnostics.constraints[kind].items" :key="item">{{ item }}</li></ul><p v-else>{{ clusterDiagnostics.constraints?.[kind]?.error || t('clusters.noConstraints') }}</p></article></div>
          <small class="data-stamp">{{ t('clusters.diagnosticsCheckedAt') }}: {{ dateLabel(clusterDiagnostics.checked_at) }}</small>
        </template>
      </section>

      <section v-else-if="activeSection === 'activity'" id="cluster-panel-activity" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.section_activity') }}</h2><p>{{ t('clusters.area_activity_description') }}</p></div><button class="btn role-secondary" :disabled="diagnosticsLoading || !activeClusterHostId" @click="fetchClusterDiagnostics">{{ diagnosticsLoading ? t('clusters.diagnosticsLoading') : t('clusters.refresh') }}</button></div>
        <div v-if="!activeClusterHostId" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ t('clusters.selectClusterForDetails') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <div v-else-if="diagnosticsLoading" class="loading compact">{{ t('clusters.diagnosticsLoading') }}</div>
        <template v-else-if="clusterDiagnostics || clusterDiagnosticsError"><div v-if="clusterDiagnosticsError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.diagnosticsError') }}</strong><p>{{ clusterDiagnosticsError }}</p></div><article v-if="clusterDiagnostics" class="diagnostic-card"><h3>{{ t('clusters.recentServiceEvents') }}</h3><pre v-if="clusterDiagnostics.activity?.available && clusterDiagnostics.activity.summary">{{ clusterDiagnostics.activity.summary }}</pre><p v-else>{{ clusterDiagnostics.activity?.error || t('clusters.noActivity') }}</p></article><small v-if="clusterDiagnostics" class="data-stamp">{{ t('clusters.diagnosticsWindow') }} · {{ dateLabel(clusterDiagnostics.checked_at) }}</small></template>
      </section>

      <section v-else-if="activeSection === 'overview'" id="cluster-panel-overview" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.readiness') }}</span><h2>{{ t('clusters.hostsTitle') }}</h2><p>{{ t('clusters.hostsDescription') }}</p></div><button class="btn role-primary" @click="goToHosts">{{ t('clusters.manageHosts') }}</button></div>
        <div v-if="!hosts.length" class="empty-state"><h3>{{ t('clusters.noHosts') }}</h3><p>{{ t('clusters.noHostsHelp') }}</p><button class="btn role-primary" @click="goToHosts">{{ t('clusters.addHost') }}</button></div>
        <div v-else class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.host') }}</th><th>{{ t('clusters.hostState') }}</th><th>{{ t('clusters.haAddon') }}</th><th>{{ t('clusters.clusterStack') }}</th><th>{{ t('clusters.clusterState') }}</th><th>{{ t('clusters.resources') }}</th><th>{{ t('clusters.checkedAt') }}</th><th></th></tr></thead>
          <tbody><tr v-for="host in hosts" :key="host.id">
            <td><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }}:{{ host.port }}</small></td>
            <td><span class="state" :class="host.status"><i></i>{{ statusLabel(host.status) }}</span><small v-if="host.last_error">{{ host.last_error }}</small></td>
            <td><span class="state" :class="haClass(host)"><i></i>{{ haLabel(host) }}</span><small v-if="host.ha?.ha_product">{{ host.ha.ha_product }}</small><small v-else-if="host.ha?.inspection_error">{{ host.ha.inspection_error }}</small><small v-else-if="host.ha?.extension_error">{{ host.ha.extension_error }}</small></td>
            <td><div class="stack-status"><span :class="serviceClass(host,'pacemaker')">{{ t('clusters.pacemaker') }}: {{ serviceLabel(host,'pacemaker') }}</span><span :class="serviceClass(host,'corosync')">{{ t('clusters.corosync') }}: {{ serviceLabel(host,'corosync') }}</span><span :class="serviceClass(host,'hawk')">{{ t('clusters.hawk') }}: {{ serviceLabel(host,'hawk') }}</span></div></td>
            <td><span class="state" :class="clusterStateClass(host)"><i></i>{{ t(clusterStateKey(host)) }}</span><small v-if="host.ha?.cluster_summary" class="cluster-summary">{{ host.ha.cluster_summary }}</small></td>
            <td>{{ host.cpu_count ? `${host.cpu_count} vCPU` : '—' }}<small>{{ memoryLabel(host.memory_total_bytes) }}</small></td>
            <td>{{ dateLabel(host.ha?.checked_at || host.last_checked_at) }}</td>
            <td><button class="btn role-link btn-sm" @click="goToSubscriptions(host)">{{ t('clusters.manageSubscription') }}</button></td>
          </tr></tbody>
        </table></div>
        <p class="safety-note">{{ t('clusters.readOnlyNote') }}</p>
      </section>

      <section v-else-if="activeSection === 'plan'" id="cluster-panel-plan" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.guidedSetup') }}</span><h2>{{ t('clusters.planTitle') }}</h2><p>{{ t('clusters.planDescription') }}</p></div><span class="planned-badge">{{ t('clusters.preparationOnly') }}</span></div>
        <ol class="setup-steps"><li v-for="(step, index) in setupSteps" :key="step" :class="{ current: index === 0 }"><span class="step-number">{{ index + 1 }}</span><div><strong>{{ t(`clusters.setup_${step}`) }}</strong><small>{{ t(`clusters.setup_${step}_help`) }}</small></div><span v-if="index > 0" class="planned-badge small">{{ t('clusters.afterHostActivation') }}</span><span v-else class="step-current">{{ t('clusters.currentStep') }}</span></li></ol>
        <div class="plan-layout">
          <div class="plan-main">
            <h3>{{ t('clusters.topologyChoices') }}</h3><p class="section-help">{{ t('clusters.topologyChoicesHelp') }}</p>
            <div class="topology-fields"><label>{{ t('clusters.clusterName') }}<input v-model.trim="plannedClusterName" type="text" maxlength="64" :placeholder="t('clusters.clusterNamePlaceholder')"></label><label>{{ t('clusters.quorumPlan') }}<select v-model="quorumPlan"><option value="pending">{{ t('clusters.chooseAfterPreflight') }}</option><option value="qdevice">{{ t('clusters.qdevicePlan') }}</option><option value="standard">{{ t('clusters.standardQuorum') }}</option></select></label><label>{{ t('clusters.fencingPlan') }}<select v-model="fencingPlan"><option value="pending">{{ t('clusters.chooseAfterPreflight') }}</option><option value="sbd">{{ t('clusters.sbdPlan') }}</option><option value="hardware">{{ t('clusters.externalFencingPlan') }}</option><option value="manual">{{ t('clusters.fencingPlanLater') }}</option></select></label></div>
            <h3>{{ t('clusters.selectNodes') }}</h3><p class="section-help">{{ t('clusters.selectNodesHelp') }}</p>
            <div v-if="!eligibleHosts.length" class="inline-callout info"><strong>{{ t('clusters.noEligibleHosts') }}</strong><p>{{ t('clusters.noEligibleHostsHelp') }}</p><button class="btn role-link" @click="activeSection = 'overview'">{{ t('clusters.openNodes') }}</button></div>
            <div v-else class="host-picker">
              <label v-for="host in eligibleHosts" :key="host.id" class="host-option"><input v-model="selectedHostIds" type="checkbox" :value="host.id"><span><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }} · {{ host.ha?.ha_product_name || host.ha?.ha_product || t('clusters.haEnabled') }}</small></span><span class="state ready"><i></i>{{ t('clusters.readyForPlanning') }}</span></label>
            </div>
            <div class="preflight-actions"><button class="btn role-primary" :disabled="preflightLoading || selectedHostIds.length < 2" @click="runPreflight">{{ preflightLoading ? t('clusters.preflightRunning') : t('clusters.runPreflight') }}</button><small>{{ t('clusters.preflightReadOnly') }}</small></div>
            <div class="stack-install"><div><strong>{{ t('clusters.installHaStackTitle') }}</strong><p>{{ t('clusters.installHaStackHelp') }}</p></div><button v-if="canManageCluster" class="btn role-secondary" :disabled="!selectedHostIds.length || stackInstallLoading" @click="pendingInstallStack = true">{{ stackInstallLoading ? t('clusters.stackInstallRunning') : t('clusters.installHaStack') }}</button><span v-else class="planned-badge">{{ t('clusters.operatorRoleRequired') }}</span></div>
            <div v-if="pendingInstallStack" class="inline-callout warning action-review"><strong>{{ t('clusters.installReviewTitle') }}</strong><p>{{ t('clusters.installReviewText', { hosts: selectedHostNames }) }}</p><small>{{ t('clusters.installReviewWarning') }}</small><div><button class="btn role-primary btn-sm" :disabled="stackInstallLoading" @click="installHaStack">{{ stackInstallLoading ? t('clusters.stackInstallRunning') : t('clusters.installHaStack') }}</button><button class="btn role-secondary btn-sm" :disabled="stackInstallLoading" @click="pendingInstallStack = false">{{ t('clusters.cancelAction') }}</button></div></div>
            <div v-if="stackInstallResults.length" class="preflight-results"><h3>{{ t('clusters.stackInstallResults') }}</h3><article v-for="item in stackInstallResults" :key="item.host_id" class="preflight-host"><div class="preflight-host-heading"><strong>{{ item.host_name }}</strong><span class="state" :class="item.status === 'installed' ? 'ready' : 'unreachable'"><i></i>{{ item.status === 'installed' ? t('clusters.stackInstalled') : t('clusters.stackInstallFailed') }}</span></div><p v-if="item.error" class="preflight-error-text">{{ item.error }}</p><p v-else class="section-help">{{ item.message }}</p></article></div>
            <div v-if="preflightError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.preflightError') }}</strong><p>{{ preflightError }}</p></div>
            <div v-if="preflightResults.length" class="preflight-results">
              <h3>{{ t('clusters.preflightResults') }}</h3>
              <article v-for="result in preflightResults" :key="result.host_id" class="preflight-host">
                <div class="preflight-host-heading"><strong>{{ result.host_name }}</strong><span class="state" :class="result.status === 'checked' ? 'ready' : 'unreachable'"><i></i>{{ result.status === 'checked' ? t('clusters.checked') : t('clusters.checkFailed') }}</span></div>
                <p v-if="result.error" class="preflight-error-text">{{ result.error }}</p>
                <template v-else-if="result.checks">
                  <div class="preflight-facts"><span><small>{{ t('clusters.operatingSystem') }}</small><strong>{{ result.checks.os_name || result.checks.os_id || '—' }}</strong></span><span><small>{{ t('clusters.architecture') }}</small><strong>{{ result.checks.architecture || '—' }}</strong></span><span><small>{{ t('clusters.hostname') }}</small><strong>{{ result.checks.hostname || '—' }}</strong></span></div>
                  <ul class="preflight-checks"><li :class="result.checks.ha_active ? 'check-ok' : 'check-blocked'">{{ result.checks.ha_active ? t('clusters.haCheckOk') : t('clusters.haCheckMissing') }}</li><li :class="result.checks.time_synchronized ? 'check-ok' : 'check-warning'">{{ result.checks.time_synchronized ? t('clusters.timeCheckOk') : t('clusters.timeCheckUnknown') }}</li><li :class="result.checks.tools?.crm && result.checks.tools?.crm_mon ? 'check-ok' : 'check-warning'">{{ result.checks.tools?.crm && result.checks.tools?.crm_mon ? t('clusters.toolsCheckOk') : t('clusters.toolsCheckMissing') }}</li><li class="check-warning">{{ t('clusters.networkCheckManual', { count: result.checks.interfaces?.length || 0 }) }}</li><li class="check-warning">{{ t('clusters.fencingCheckManual', { count: result.checks.watchdog_devices?.length || 0 }) }}</li></ul>
                </template>
              </article>
              <div v-if="preflightCompatibilityWarning" class="inline-callout warning"><strong>{{ t('clusters.compatibilityWarning') }}</strong><p>{{ preflightCompatibilityWarning }}</p></div>
            </div>
            <div v-if="selectedClusterHosts.length >= 2" class="bootstrap-guide"><div><span class="eyebrow">{{ t('clusters.bootstrapGuide') }}</span><h3>{{ t('clusters.bootstrapTitle') }}</h3><p>{{ t('clusters.bootstrapHelp') }}</p></div><div v-if="!preflightReadyForBootstrap" class="inline-callout warning"><strong>{{ t('clusters.preflightRequiredForBootstrap') }}</strong></div><div v-else-if="!validClusterName" class="inline-callout warning"><strong>{{ t('clusters.clusterNameInvalid') }}</strong></div><template v-else><article><div><strong>1 · {{ t('clusters.initializeFirstNode', { host: selectedClusterHosts[0].hostname || selectedClusterHosts[0].name }) }}</strong><button class="btn role-secondary btn-sm" @click="copyBootstrapCommand(initCommand)">{{ t('clusters.copyCommand') }}</button><button class="btn role-primary btn-sm" @click="openHostTerminal(selectedClusterHosts[0])">{{ t('clusters.openHostTerminal') }}</button></div><code>{{ initCommand }}</code></article><article v-for="host in selectedClusterHosts.slice(1)" :key="host.id"><div><strong>{{ t('clusters.joinAdditionalNode', { host: host.hostname || host.name }) }}</strong><button class="btn role-secondary btn-sm" @click="copyBootstrapCommand(joinCommand(host))">{{ t('clusters.copyCommand') }}</button><button class="btn role-primary btn-sm" @click="openHostTerminal(host)">{{ t('clusters.openHostTerminal') }}</button></div><code>{{ joinCommand(host) }}</code></article></template><small>{{ t('clusters.bootstrapSafety') }}</small><span v-if="copyFeedback" role="status" class="copy-feedback">{{ copyFeedback }}</span></div>
            <div v-if="selectedHostIds.length === 2" class="inline-callout warning" role="note"><strong>{{ t('clusters.twoNodeTitle') }}</strong><p>{{ t('clusters.twoNodeHelp') }}</p><p>{{ t('clusters.qnetdPlacement') }}</p></div>
            <div v-else-if="selectedHostIds.length > 2 && selectedHostIds.length % 2 === 0" class="inline-callout info" role="note"><strong>{{ t('clusters.evenNodeTitle') }}</strong><p>{{ t('clusters.evenNodeHelp') }}</p></div>
            <div v-else-if="selectedHostIds.length >= 3" class="inline-callout success" role="status"><strong>{{ t('clusters.oddNodeTitle') }}</strong><p>{{ t('clusters.oddNodeHelp') }}</p></div>
            <div v-else class="inline-callout info" role="status"><strong>{{ t('clusters.selectAtLeastTwo') }}</strong><p>{{ t('clusters.selectAtLeastTwoHelp') }}</p></div>
          </div>
          <aside class="plan-summary"><span class="eyebrow">{{ t('clusters.topologySummary') }}</span><strong>{{ selectedHostIds.length }} {{ t('clusters.selectedNodes') }}</strong><p><b>{{ t('clusters.clusterName') }}:</b> {{ plannedClusterName || t('clusters.notChosen') }}</p><p><b>{{ t('clusters.quorum') }}:</b> {{ t(`clusters.quorum_${quorumPlan}`) }}</p><p><b>{{ t('clusters.fencing') }}:</b> {{ t(`clusters.fencing_${fencingPlan}`) }}</p><p>{{ t('clusters.summaryNetworks') }}</p><div class="summary-divider"></div><span class="planned-badge">{{ t('clusters.planOnlyLabel') }}</span></aside>
        </div>
        <div class="practice-grid"><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceFailureDomains') }}</strong><p>{{ t('clusters.practiceFailureDomainsHelp') }}</p></div></article><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceFencing') }}</strong><p>{{ t('clusters.practiceFencingHelp') }}</p></div></article><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceNetwork') }}</strong><p>{{ t('clusters.practiceNetworkHelp') }}</p></div></article></div>
        <p class="safety-note">{{ t('clusters.planSafety') }}</p>
      </section>

      <section v-else :id="`cluster-panel-${activeSection}`" class="cluster-panel" role="tabpanel">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t(`clusters.section_${activeSection}`) }}</h2><p>{{ t(`clusters.area_${activeSection}_description`) }}</p></div><span class="planned-badge">{{ t('clusters.availableAfterCluster') }}</span></div>
        <div class="section-preview"><div class="preview-icon" aria-hidden="true">{{ sectionIcon(activeSection) }}</div><div><h3>{{ t('clusters.sectionPreviewTitle') }}</h3><p>{{ t('clusters.sectionPreviewHelp') }}</p></div></div>
        <div v-if="activeSection === 'fencing'" class="inline-callout warning"><strong>{{ t('clusters.fencingRequiredTitle') }}</strong><p>{{ t('clusters.fencingRequiredHelp') }}</p></div>
        <div v-else-if="activeSection === 'nodes'" class="inline-callout info"><strong>{{ t('clusters.nodesPreviewTitle') }}</strong><p>{{ t('clusters.nodesPreviewHelp') }}</p><button class="btn role-link" @click="activeSection = 'overview'">{{ t('clusters.viewHostChecks') }}</button></div>
        <p class="safety-note">{{ t('clusters.hawkRoadmapSafety') }}</p>
      </section>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

type HaStatus = { suseconnect_available?: boolean; ha_available?: boolean; ha_active?: boolean; ha_product?: string; ha_product_name?: string; extension_error?: string; commands?: Record<string, boolean>; services?: Record<string, string>; cluster_detected?: boolean; cluster_name?: string; cluster_summary?: string; inspection_error?: string; checked_at?: string };
type Host = { id: string; name: string; address: string; port: number; hostname?: string; status: string; cpu_count?: number; memory_total_bytes?: number; last_checked_at?: string; last_error?: string; ha?: HaStatus };
type ClusterNode = { id: string; name: string; online: boolean; standby: boolean; maintenance: boolean; unclean: boolean; pending?: string };
type ClusterResource = { id: string; agent?: string; role?: string; active: boolean; failed: boolean; managed: boolean; nodes?: string[] };
type ClusterStatus = { cluster_name?: string; nodes: ClusterNode[]; resources: ClusterResource[]; node_count: number; online_count: number; resource_count: number; quorum?: { available?: boolean; quorate?: boolean; summary?: string }; fencing?: { available?: boolean; configured?: boolean; summary?: string }; checked_at?: string; source_host_id: string; source_host_name: string };
type ClusterDiagnostics = { checked_at?: string; hawk_url?: string; constraints?: Record<string,{available?:boolean;items?:string[];error?:string}>; corosync?: {available?:boolean;summary?:string;error?:string}; activity?: {available?:boolean;summary?:string;error?:string} };
type StackInstallResult = { host_id: string; host_name: string; status: string; message?: string; error?: string };
type PreflightChecks = { os_id?: string; os_name?: string; os_version?: string; architecture?: string; hostname?: string; ha_active?: boolean; time_synchronized?: boolean; tools?: Record<string, boolean>; interfaces?: unknown[]; watchdog_devices?: unknown[] };
type PreflightResult = { host_id: string; host_name: string; status: string; error?: string; checks?: PreflightChecks };
const apiBase = (process.env.VUE_APP_KVM_API || '/kvm-api').replace(/\/$/, '');

export default defineComponent({
  name: 'KvmClusters',
  data() { return { hosts: [] as Host[], loading: false, loaded: false, error: '', refreshTimer: 0 as number, refreshingStale: false, activeSection: 'clusters', selectedHostIds: [] as string[], preflightLoading: false, preflightError: '', preflightResults: [] as PreflightResult[], pendingInstallStack: false, stackInstallLoading: false, stackInstallResults: [] as StackInstallResult[], clusterStatus: null as ClusterStatus | null, activeClusterHostId: '', clusterStatusLoading: false, clusterStatusError: '', clusterDiagnostics: null as ClusterDiagnostics | null, clusterDiagnosticsError: '', diagnosticsLoading: false, plannedClusterName: '', quorumPlan: 'pending', fencingPlan: 'pending', copyFeedback: '', pendingClusterAction: null as null | { action: string; target: string }, clusterActionBusy: false, clusterActionError: '', clusterActionMessage: '', canManageCluster: false, sections: ['clusters','nodes','resources','constraints','activity','fencing','plan','overview'], setupSteps: ['nodes','preflight','topology','review','configure'] }; },
  watch: { selectedHostIds() { this.preflightResults = []; this.preflightError = ''; } },
  mounted() { this.load(); this.refreshTimer = window.setInterval(() => { if (document.visibilityState === 'visible') this.refreshStale(); }, 60000); },
  beforeUnmount() { window.clearInterval(this.refreshTimer); },
  computed: {
    haEnabledCount(): number { return this.hosts.filter((host) => host.ha?.ha_active).length; },
    clusterHostCount(): number { return this.hosts.filter((host) => host.ha?.cluster_detected).length; },
    clusterHosts(): Host[] { const seen = new Set<string>(); return this.hosts.filter((host) => { if (!host.ha?.cluster_detected) return false; const key = host.ha.cluster_name || host.id; if (seen.has(key)) return false; seen.add(key); return true; }); },
    quorumSummary(): string { const value = this.clusterStatus?.quorum?.summary?.split('\n').find((line) => /quorate|quorum|votes|expected/i.test(line)); return value?.trim() || this.t('clusters.quorumHelp'); },
    fencingSummary(): string { const value = this.clusterStatus?.fencing?.summary?.trim(); return value ? value.split('\n').slice(0,2).join(' · ') : this.t('clusters.fencingHelp'); },
    actionReviewText(): string { if (!this.pendingClusterAction) return ''; return this.t(`clusters.review_${this.pendingClusterAction.action}`, { target: this.pendingClusterAction.target }); },
    selectedHostNames(): string { return this.hosts.filter((host) => this.selectedHostIds.includes(host.id)).map((host) => host.hostname || host.name).join(', '); },
    selectedClusterHosts(): Host[] { return this.selectedHostIds.map((id) => this.hosts.find((host) => host.id === id)).filter((host): host is Host => Boolean(host)); },
    validClusterName(): boolean { return /^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/.test(this.plannedClusterName); },
    preflightReadyForBootstrap(): boolean { return this.selectedHostIds.length >= 2 && this.preflightResults.length === this.selectedHostIds.length && this.selectedHostIds.every((id) => this.preflightResults.some((result) => result.host_id === id && result.status === 'checked' && result.checks?.ha_active && result.checks?.time_synchronized && result.checks?.tools?.crm && result.checks?.tools?.crm_mon)); },
    initCommand(): string { return `sudo crm cluster init --name ${this.shellArg(this.plannedClusterName)}`; },
    eligibleHosts(): Host[] { return this.hosts.filter((host) => host.status === 'ready' && host.ha?.ha_active && !host.ha?.cluster_detected); },
    preflightCompatibilityWarning(): string { const checked = this.preflightResults.filter((item) => item.checks).map((item) => item.checks!); if (checked.length < 2) return ''; const architectures = [...new Set(checked.map((item) => item.architecture).filter(Boolean))]; const releases = [...new Set(checked.map((item) => `${item.os_id}:${item.os_version}`).filter((item) => item !== ':'))]; const issues = [architectures.length > 1 ? this.t('clusters.architectureMismatch') : '', releases.length > 1 ? this.t('clusters.releaseMismatch') : ''].filter(Boolean); return issues.join(' '); },
  },
  methods: {
    t(key: string, args?: Record<string, unknown>): string { const translate = (this as any).$store?.getters?.['i18n/t']; return translate ? translate(`kvmManager.${key}`, args) : key; },
    async load() { this.loading = true; this.error = ''; try { await Promise.all([this.fetchReadiness(), this.fetchPermissions()]); } catch (error) { this.error = `${this.t('clusters.loadError')}: ${(error as Error).message}`; } finally { this.loading = false; this.loaded = true; } },
    async fetchPermissions() { try { const response = await fetch(`${apiBase}/permissions`, { credentials: 'include', cache: 'no-store' }); if (response.ok) { const body = await response.json(); this.canManageCluster = Boolean(body.canManageHostResources || body.canAdministerHost); } } catch { this.canManageCluster = false; } },
    async fetchReadiness() { const response = await fetch(`${apiBase}/clusters/readiness`, { credentials: 'include', cache: 'no-store' }); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.detail || `API request failed (${response.status})`); } this.hosts = await response.json(); this.selectedHostIds = this.selectedHostIds.filter((id) => this.eligibleHosts.some((host) => host.id === id)); const source = this.clusterHosts.find((host) => host.id === this.activeClusterHostId) || this.clusterHosts[0]; if (source && !this.clusterStatusLoading) { this.activeClusterHostId = source.id; await this.fetchClusterStatus(); } else if (!source) { this.activeClusterHostId = ''; this.clusterStatus = null; this.clusterStatusError = ''; } },
    async fetchClusterStatus() { if (!this.activeClusterHostId) return; this.clusterStatusLoading = true; this.clusterStatusError = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/status`, { credentials: 'include', cache: 'no-store' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.clusterStatus = body; } catch (error) { this.clusterStatus = null; this.clusterStatusError = (error as Error).message; } finally { this.clusterStatusLoading = false; } },
    async fetchClusterDiagnostics() { if (!this.activeClusterHostId) return; this.diagnosticsLoading = true; this.clusterDiagnosticsError = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/diagnostics`, { credentials: 'include', cache: 'no-store' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.clusterDiagnostics = body; } catch (error) { this.clusterDiagnostics = null; this.clusterDiagnosticsError = (error as Error).message; } finally { this.diagnosticsLoading = false; } },
    async selectSection(section: string) { this.activeSection = section; if ((section === 'constraints' || section === 'activity' || section === 'fencing') && this.activeClusterHostId) await this.fetchClusterDiagnostics(); },
    shellArg(value: string): string { return `'${value.replace(/'/g, "'\\''")}'`; },
    joinCommand(host: Host): string { const first = this.selectedClusterHosts[0]; return `sudo crm cluster join --cluster-node ${this.shellArg(first.hostname || first.name)}`; },
    openHostTerminal(host: Host) { this.$router.push({ name: 'kvm-c-cluster-cloud-native', query: { hostId: host.id, tab: 'terminal' } }); },
    async copyBootstrapCommand(command: string) { try { await navigator.clipboard.writeText(command); this.copyFeedback = this.t('clusters.commandCopied'); window.setTimeout(() => { this.copyFeedback = ''; }, 2500); } catch { this.copyFeedback = this.t('clusters.copyFailed'); } },
    async openCluster(host: Host) { this.activeClusterHostId = host.id; this.clusterActionError = ''; this.clusterActionMessage = ''; await Promise.all([this.fetchClusterStatus(), this.fetchClusterDiagnostics()]); if (this.clusterStatus) this.activeSection = 'nodes'; },
    requestClusterAction(action: string, target: string) { if (!this.canManageCluster) return; this.pendingClusterAction = { action, target }; this.clusterActionError = ''; this.clusterActionMessage = ''; },
    async runClusterAction() { if (!this.pendingClusterAction || !this.activeClusterHostId) return; const action = this.pendingClusterAction; this.clusterActionBusy = true; this.clusterActionError = ''; this.clusterActionMessage = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/actions`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(action) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.clusterActionMessage = body.message || this.t('clusters.actionSucceeded'); this.pendingClusterAction = null; await this.fetchClusterStatus(); } catch (error) { this.clusterActionError = (error as Error).message; } finally { this.clusterActionBusy = false; } },
    async runPreflight() { if (this.selectedHostIds.length < 2) return; this.preflightLoading = true; this.preflightError = ''; this.preflightResults = []; try { const response = await fetch(`${apiBase}/clusters/preflight`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ host_ids: this.selectedHostIds }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.preflightResults = body; } catch (error) { this.preflightError = (error as Error).message; } finally { this.preflightLoading = false; } },
    async installHaStack() { if (!this.selectedHostIds.length) return; this.stackInstallLoading = true; this.stackInstallResults = []; this.preflightError = ''; try { const response = await fetch(`${apiBase}/clusters/install-stack`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ host_ids: this.selectedHostIds }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.stackInstallResults = body; this.pendingInstallStack = false; await this.fetchReadiness(); } catch (error) { this.preflightError = (error as Error).message; } finally { this.stackInstallLoading = false; } },
    async refreshStale() { if (this.refreshingStale || !this.hosts.length) return; this.refreshingStale = true; try { await this.fetchReadiness(); } catch { /* Keep the latest host status visible during transient API failures. */ } finally { this.refreshingStale = false; } },
    goToHosts() { this.$router.push({ name: 'kvm-hosts' }); },
    goToSubscriptions(host: Host) { this.$router.push({ name: 'kvm-c-cluster-cloud-native', query: { hostId: host.id, tab: 'subscriptions' } }); },
    sectionIcon(section: string) { return ({ clusters: '◇', overview: '◉', plan: '⌁', nodes: '▤', resources: '◆', constraints: '⌘', activity: '≋', fencing: '⬡' } as Record<string,string>)[section] || '•'; },
    statusLabel(status: string) { return this.t(`hosts.${status === 'ready' ? 'ready' : status === 'unreachable' ? 'unreachable' : 'unknown'}`); },
    haLabel(host: Host) { const ha = host.ha; if (ha?.inspection_error || ha?.extension_error || !ha?.suseconnect_available) return this.t('clusters.haUnknown'); if (ha.ha_active) return this.t('clusters.haEnabled'); if (ha.ha_available) return this.t('clusters.haAvailable'); return this.t('clusters.haUnavailable'); },
    haClass(host: Host) { const ha = host.ha; return ha?.inspection_error || ha?.extension_error || !ha?.suseconnect_available ? 'unknown' : ha.ha_active ? 'ready' : ha.ha_available ? 'warning-state' : 'unreachable'; },
    serviceLabel(host: Host, name: string) { const state = host.ha?.services?.[name]; return this.t(state === 'active' ? 'clusters.active' : state === 'inactive' || state === 'failed' ? 'clusters.inactive' : 'clusters.notInstalled'); },
    serviceClass(host: Host, name: string) { const state = host.ha?.services?.[name]; return state === 'active' ? 'service-active' : state === 'inactive' || state === 'failed' ? 'service-inactive' : 'service-missing'; },
    clusterStateKey(host: Host) { const ha = host.ha; if (ha?.inspection_error) return 'clusters.haUnknown'; if (!ha?.ha_active) return 'clusters.notApplicable'; if (ha.cluster_detected) return 'clusters.clusterDetected'; if (!ha.commands?.crm || !ha.commands?.crm_mon) return 'clusters.haStackMissing'; if (ha.services?.pacemaker !== 'active' || ha.services?.corosync !== 'active') return 'clusters.haStackStopped'; return 'clusters.clusterNotInitialized'; },
    clusterStateClass(host: Host) { const key = this.clusterStateKey(host); return key === 'clusters.clusterDetected' ? 'ready' : key === 'clusters.haUnknown' ? 'unknown' : key === 'clusters.clusterNotInitialized' ? 'warning-state' : 'unreachable'; },
    memoryLabel(bytes?: number) { if (!bytes) return '—'; const gib = bytes / 1024 ** 3; return `${gib.toFixed(gib >= 10 ? 0 : 1)} GiB`; },
    dateLabel(value?: string) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString(); },
  },
});
</script>

<style scoped>
.clusters-page { padding:26px; }.clusters-header,.panel-heading { display:flex; align-items:flex-start; justify-content:space-between; gap:20px; }.clusters-header { margin-bottom:22px; }.clusters-header h1 { margin:4px 0 0; font-size:24px; font-weight:500; }.clusters-header p,.panel-heading p { margin:6px 0 0; color:var(--muted,#8b95a5); }.eyebrow { color:var(--muted,#8b95a5); font-size:11px; font-weight:700; letter-spacing:.06em; }
.cluster-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px; margin-bottom:18px; }.cluster-stats article,.cluster-panel { padding:18px; border:1px solid var(--border,#394452); border-radius:8px; background:var(--body-bg,#252b33); }.cluster-stats article { display:grid; gap:8px; }.cluster-stats article>span,.cluster-stats small { color:var(--muted,#8b95a5); font-size:12px; }.cluster-stats strong { font-size:24px; }
.cluster-nav { display:flex; gap:4px; margin-bottom:14px; padding:5px; overflow-x:auto; border:1px solid var(--border,#394452); border-radius:8px; background:var(--body-bg,#252b33); }.cluster-nav-item { display:inline-flex; align-items:center; gap:8px; min-height:38px; padding:0 12px; border:0; border-radius:5px; color:var(--muted,#9ca6b4); background:transparent; white-space:nowrap; cursor:pointer; }.cluster-nav-item:hover { color:var(--body-text,#e7e9ec); background:rgba(128,145,163,.1); }.cluster-nav-item[aria-selected="true"] { color:var(--success,#53ba84); background:rgba(65,180,124,.13); font-weight:600; box-shadow:inset 0 -2px var(--success,#53ba84); }.cluster-nav-item:focus-visible { outline:2px solid var(--success,#53ba84); outline-offset:2px; }.nav-icon { width:17px; text-align:center; font-size:15px; }.nav-count { min-width:20px; padding:2px 5px; border-radius:10px; color:var(--body-text,#e7e9ec); background:rgba(128,145,163,.18); font-size:10px; text-align:center; }
.cluster-panel { margin-bottom:18px; min-height:260px; }.panel-heading { align-items:center; margin-bottom:16px; }.panel-heading h2 { margin:4px 0 0; font-size:19px; }.panel-heading p { max-width:900px; font-size:13px; line-height:1.5; }.cluster-panel .empty-state { padding:32px 20px; }.empty-state h3 { margin:0 0 6px; }.empty-state p { margin:0 0 18px; }
.table-wrap { overflow:auto; }.table { width:100%; border-collapse:collapse; }.table th,.table td { padding:11px 12px; border-bottom:1px solid var(--border,#394452); text-align:left; font-size:12px; vertical-align:top; }.table th { color:var(--muted,#8b95a5); font-size:10px; text-transform:uppercase; white-space:nowrap; }.table td small { display:block; max-width:220px; margin-top:4px; color:var(--muted,#8b95a5); overflow-wrap:anywhere; }.state { display:inline-flex; align-items:center; gap:6px; white-space:nowrap; }.state i { width:7px; height:7px; border-radius:50%; background:#a1a8b3; }.state.ready i { background:#45b879; }.state.unreachable i { background:#e36c68; }.state.warning-state i { background:#e6b84c; }.stack-status { display:grid; gap:5px; white-space:nowrap; font-size:11px; }.service-active { color:#65d39b; }.service-inactive { color:#e6b84c; }.service-missing { color:var(--muted,#8b95a5); }.cluster-summary { max-width:260px !important; white-space:pre-line; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:10px !important; }
.planned-badge { display:inline-flex; align-items:center; border:1px solid var(--border,#394452); border-radius:99px; padding:5px 10px; color:var(--muted,#9ca6b4); font-size:11px; white-space:nowrap; }.planned-badge.small { padding:3px 8px; }.safety-note { margin:14px 0 0; color:var(--muted,#8b95a5); font-size:12px; line-height:1.5; }.loading { padding:48px; text-align:center; color:var(--muted,#8b95a5); }.loading.compact { padding:18px; }.banner.error { margin:14px 0; padding:13px; border-radius:6px; color:#8f211a; background:#fff0ee; }
